            try:
                qty = int(s)
            except ValueError:
                try:
                    qty = float(s)
                except ValueError:
                    continue
        else:
            continue

        net[key] = net.get(key, 0) + qty

    # Deterministic output ordering for the JSON object
    return {k: net[k] for k in sorted(net)}
