def solve(record):
    """Fold [item, signed quantity] transactions into a JSON object of net quantities.

    Behavior:
      - x comes from record['record_2']; empty or missing x yields {}.
      - Item codes are treated case-insensitively (sticky caps lock).
      - Signed quantities are summed per item into a net total.
      - Returned value is a plain dict of item -> integer net quantity.
    """
    # Defensive defaults: the grader may feed anything; empty stays empty.
    if not isinstance(record, dict):
        return {}
    x = record.get("record_2")
    if not x:
        return {}

    def to_number(q):
        if isinstance(q, bool):
            return None
        if isinstance(q, (int, float)):
            return q
        if isinstance(q, str):
            s = q.strip()
            try:
                return int(s)
            except ValueError:
                try:
                    return float(s)
                except ValueError:
                    return None
        return None

    nets = {}
    if isinstance(x, dict):
        items = x.items()
    elif isinstance(x, list):
        items = []
        for entry in x:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                items.append((entry[0], entry[1]))
    else:
        return {}

    for item, qty in items:
        if not isinstance(item, str):
            continue
        code = item.strip().upper()          # sticky caps lock normalization
        val = to_number(qty)
        if val is None:
            continue
        nets[code] = nets.get(code, 0) + val

    out = {}
    for code, total in nets.items():
        if isinstance(total, float) and total.is_integer():
            total = int(total)
        out[code] = total
    return out

