    """Return the number of edges in the shortest route from source to target.

    Input: record['record_3'] = [edges, source, target]
    where edges is a list of directed pairs [from, to].

    Returns an int (edge count) or -1 if no route exists / malformed input.
    """
    def _fail():
        return -1

    if not isinstance(record, dict) or "record_3" not in record:
        return _fail()
    x = record["record_3"]
    if not (isinstance(x, (list, tuple)) and len(x) >= 3):
        return _fail()
    edges, src, dst = x[0], x[1], x[2]

    from collections import deque

    adj = {}
    if isinstance(edges, (list, tuple)):
        for e in edges:
            if isinstance(e, (list, tuple)) and len(e) >= 2:
                a, b = e[0], e[1]
                adj.setdefault(a, []).append(b)
                adj.setdefault(b, [])

    if src == dst:
        return 0

    seen = {src}
    q = deque([(src, 0)])
    while q:
        node, d = q.popleft()
        for nxt in adj.get(node, ()):
            if nxt == dst:
                return d + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))

    return _fail()
