def solve(record):
    """Fold [item, signed quantity] transactions in record['record_3']
    into a JSON object of net quantities.

    The shelf-report data flow for a hardware company:
      - Each transaction is [item_code, signed_quantity].
      - Item codes are typed on a scanner/human keyboard where caps lock
        may be sticky, so codes are canonicalised to uppercase.
      - Quantities are summed per item to produce active net balances.
      - Malformed rows are ignored; the function never raises.

    Returns native Python values (a dict), suitable for JSON serialisation.
    """
    import json

    # Locate the transaction list x = record['record_3'].
    if not isinstance(record, dict):
        return {}
    x = record.get("record_3")

    # The payload may be a JSON string or an already-parsed list.
    if isinstance(x, str):
        try:
            x = json.loads(x)
        except Exception:
            return {}
    if not isinstance(x, (list, tuple)):
        return {}

    net = {}

    for row in x:
        # Each transaction should be a [item, signed_quantity] pair.
        if not isinstance(row, (list, tuple)) or len(row) < 2:
            continue
        code, qty = row[0], row[1]

        # Item codes are strings from a keyboard with sticky caps lock:
        # trim stray whitespace and fold to uppercase for matching.
        if not isinstance(code, str):
            continue
        key = code.strip().upper()
        if not key:
            continue

        # Quantities may be native numbers or numeric strings.
        if isinstance(qty, bool):
            continue
        if isinstance(qty, int):
            amount = qty
        elif isinstance(qty, float):
            if not float(qty).is_integer():
                continue
            amount = int(qty)
        elif isinstance(qty, str):
            text = qty.strip()
            try:
                amount = int(text)
            except ValueError:
                try:
                    amount = int(float(text))
                except ValueError:
                    continue
        else:
            continue

        net[key] = net.get(key, 0) + amount

    # Emit a plain JSON object of net quantities.
    return net
