def solve(record):
    """Normalize a slash-separated relative path from record['record_0'].

    - Repeated slashes produce empty separators and are ignored.
    - '.' is the working-directory marker and is dropped.
    - '..' ascends one level; leading '..' entries are preserved because
      the export may refer to an ancestor outside the current directory.
    - Components are compared case-sensitively (the filesystem is case-aware).
    - The result is a list of normalized components, in order.
    - An empty path normalizes to [].
    """
    try:
        x = record["record_0"]
    except Exception:
        return []

    if not isinstance(x, str):
        x = ""

    parts = []
    for comp in x.split("/"):
        if comp == "" or comp == ".":
            # Empty components come from repeated slashes or a trailing slash;
            # '.' just means the current directory, so both are skipped.
            continue
        if comp == "..":
            # Pop the previous component unless it is itself a leading '..',
            # in which case we are already at or above the current directory.
            if parts and parts[-1] != "..":
                parts.pop()
            else:
                parts.append("..")
        else:
            parts.append(comp)

    return parts
