def solve(record):
    import collections

    if not isinstance(record, dict):
        return None
    x = record.get("record_1")
    if not isinstance(x, (list, tuple)) or len(x) != 3:
        return None

    edges, source, target = x[0], x[1], x[2]
    if not isinstance(source, str) or not isinstance(target, str):
        return None

    adj = collections.defaultdict(list)
    if isinstance(edges, (list, tuple)):
        for e in edges:
            if (isinstance(e, (list, tuple)) and len(e) == 2
                    and isinstance(e[0], str) and isinstance(e[1], str)):
                adj[e[0]].append(e[1])

    if source == target:
        # A self-transfer must form a positive-length round trip:
        # find the shortest cycle (>= 1 edge) that returns to source.
        best = None
        dist = {source: 0}
        q = collections.deque([(source, 0)])
        while q:
            node, d = q.popleft()
            for nxt in adj[node]:
                if nxt == source:
                    if best is None or d + 1 < best:
                        best = d + 1
                elif nxt not in dist:
                    dist[nxt] = d + 1
                    q.append((nxt, d + 1))
        return best

    dist = {source: 0}
    q = collections.deque([source])
    while q:
        node = q.popleft()
        d = dist[node]
        if node == target:
            return d
        for nxt in adj[node]:
            if nxt not in dist:
                dist[nxt] = d + 1
                q.append(nxt)

    return None

