def solve(record):
    """Return number of edges on shortest directed route from source to target.

    x = record['record_0'] should be [edges, source, target], where edges is a
    list of [from, to] pairs of names. Directed edges. Returns 0 if source
    equals target, -1 if target unreachable, else the minimum edge count.
    """
    try:
        x = record["record_0"]
        edges, source, target = x[0], x[1], x[2]
    except Exception:
        return -1

    if source == target:
        return 0

    adj = {}
    for edge in edges:
        try:
            a, b = edge
        except (TypeError, ValueError):
            continue
        adj.setdefault(a, []).append(b)

    from collections import deque
    queue = deque([(source, 0)])
    visited = {source}

    while queue:
        node, dist = queue.popleft()
        for nxt in adj.get(node, ()):  # directed
            if nxt == target:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, dist + 1))

    return -1

